import json
from datetime import datetime,timezone
import numpy as np,pandas as pd,scipy.sparse as sp
r=PROJECT_ROOT/'runs/20261106_v7_publication_marker_annotation_v1';a=r/'stage_a_full_axis';c=r/'stage_h_selective_subtype_restore_v4';o=r/'stage_i_selective_annotation_marker_evidence_v4';o.mkdir(exist_ok=False)
assert json.loads((c/'independent_audit.json').read_text())['status']=='PASS_selective_subtype_preservation_and_complete_export'
t=pd.read_pickle(c/'all_axis_selective_annotation_with_history_PRIVATE.pkl.gz');q=pd.read_pickle(a/'all_cells_identity_evidence_PRIVATE.pkl.gz');assert t.index.equals(q.index)
raw=np.load(a/'marker_counts_PRIVATE.npy',mmap_mode='r');total=np.load(a/'full_raw_library_totals_PRIVATE.npy');genes=np.load(a/'gene_symbols.npy').tolist();source=pd.read_csv(a/'source_axis.tsv',sep='\t').source.astype(str);av=np.load(a/'source_gene_measured.npy');si=pd.Index(source).get_indexer(q.gse_id.astype(str));take=t.annotation_frozen.to_numpy();ids=np.flatnonzero(take);labels=pd.Index(sorted(t.loc[take,'final_annotation'].astype(str).unique()));cc=labels.get_indexer(t.loc[take,'final_annotation'].astype(str));K=len(labels);G=len(genes);n=np.bincount(cc,minlength=K);den=np.zeros((K,G),np.int64);nz=np.zeros_like(den);cp=np.zeros((K,G));src=np.zeros((K,len(source)),np.int64)
for left in range(0,len(ids),30000):
 right=min(len(ids),left+30000);pos=ids[left:right];cl=cc[left:right];x=raw[pos];H=sp.csr_matrix((np.ones(len(pos),np.int64),(cl,np.arange(len(pos)))),shape=(K,len(pos)));den+=np.asarray(H@av[si[pos]].astype(np.int64));nz+=np.asarray(H@(x>0).astype(np.int64));cp+=np.asarray(H@(x*(10000.0/np.maximum(total[pos],1)[:,None])));S=sp.csr_matrix((np.ones(len(pos),np.int64),(np.arange(len(pos)),si[pos])),shape=(len(pos),len(source)));src+=np.asarray((H@S).toarray())
rows=[{'final_annotation':str(labels[i]),'gene':gene,'n_frozen_cells':int(n[i]),'n_measured':int(den[i,j]),'n_expressing':int(nz[i,j]),'coverage_fraction':float(den[i,j]/n[i]),'pct_expressing_measured':float(nz[i,j]/den[i,j]) if den[i,j] else np.nan,'mean_cp10k_measured':float(cp[i,j]/den[i,j]) if den[i,j] else np.nan} for i in range(K) for j,gene in enumerate(genes)]
pd.DataFrame(rows).to_csv(o/'frozen_label_marker_expression.tsv',sep='\t',index=False,na_rep='NA');summ=[];nameproof=[]
for i,label in enumerate(labels):
 tt=t.loc[t.final_annotation.eq(label)];markers=[g for g in dict.fromkeys(';'.join(tt.representative_markers.astype(str).unique()).split(';')) if g];record={'final_parent':str(tt.final_parent.iloc[0]),'final_annotation':label,'n_frozen_cells':len(tt),'n_sources':int((src[i]>0).sum()),'max_source_fraction':float(src[i].max()/src[i].sum()),'n_audit_groups':tt.audit_group.nunique(),'n_previous_named_annotation_retained':int(tt.prior_named_annotation_retained.sum()),'n_major_marker_fallback':int((~tt.prior_named_annotation_retained).sum()),'representative_markers':';'.join(markers),'raw_IFN_programme_positive':int(tt.raw_IFN_programme_positive.sum()),'raw_cycling_programme_positive':int(tt.raw_cycling_programme_positive.sum()),'raw_heat_shock_programme_positive':int(tt.raw_heat_shock_programme_positive.sum())};summ.append(record)
 for gene in markers:
  j=genes.index(gene);nameproof.append({'final_annotation':label,'naming_marker':gene,'n_frozen_cells':len(tt),'n_measured':int(den[i,j]),'coverage_fraction':float(den[i,j]/len(tt)),'pct_expressing_measured':float(nz[i,j]/den[i,j]) if den[i,j] else np.nan,'mean_CP10K_measured':float(cp[i,j]/den[i,j]) if den[i,j] else np.nan})
pd.DataFrame(summ).to_csv(o/'frozen_label_identity_state_summary.tsv',sep='\t',index=False);pd.DataFrame(nameproof).to_csv(o/'frozen_naming_marker_support.tsv',sep='\t',index=False)
assert sum(z['n_frozen_cells'] for z in summ)==int(take.sum())
out={'status':'selective_annotation_expression_aggregated_no_new_subtype_acceptance','UTC':datetime.now(timezone.utc).isoformat(),'n_frozen_cells':int(take.sum()),'n_labels':K,'n_genes':G,'n_records':len(rows),'source_denominators_preserved':True,'all_fallback_naming_markers_have_positive_measured_support':all(x['pct_expressing_measured']>0 for x in nameproof)};assert out['all_fallback_naming_markers_have_positive_measured_support'];(o/'complete.json').write_text(json.dumps(out,indent=2));print(json.dumps(out))
